### 2. Función RPC Transaccional en PostgreSQL (ACID + Locks)

Para procesar el cobro dividido y la afectación de inventario (supermercado) de forma atómica, implementamos una función RPC en PL/pgSQL que utiliza **`SELECT ... FOR UPDATE`** para prevenir concurrencias y bloqueos lógicos en el stock y los saldos.

```sql
CREATE OR REPLACE FUNCTION procesar_cobro_dividido_supermercado(
    p_id_tenant UUID,
    p_id_caja UUID,
    p_id_comanda UUID,
    p_pagos JSONB,
    p_items JSONB
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_item JSONB;
    v_pago JSONB;
    v_monto_total NUMERIC(12,2) := 0;
    v_suma_pagos NUMERIC(12,2) := 0;
    v_id_factura UUID;
    v_stock_actual NUMERIC(12,3);
    v_saldo_cliente NUMERIC(12,2);
BEGIN
    -- 1. Establecer contexto de seguridad Multi-Tenant estricto
    IF current_setting('request.jwt.claim.sub', true) IS NULL THEN
        RAISE EXCEPTION 'Acceso denegado: Contexto de seguridad ausente.';
    END IF;

    -- 2. Bloquear y validar estado de la comanda
    PERFORM 1 
    FROM comandas 
    WHERE id = p_id_comanda 
      AND id_tenant = p_id_tenant 
      AND estado = 'PENDIENTE'
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La comanda % no existe o ya fue procesada.', p_id_comanda;
    END IF;

    -- 3. Calcular montos y validar pagos en JSONB
    FOR v_pago IN SELECT * FROM jsonb_array_elements(p_pagos)
    LOOP
        v_suma_pagos := v_suma_pagos + (v_pago->>'monto')::NUMERIC;

        -- Si usa cuenta corriente, aplicar lock pesimista sobre el saldo del cliente
        IF v_pago->>'metodo' = 'CUENTA_CORRIENTE' THEN
            SELECT saldo_actual INTO v_saldo_cliente
            FROM clientes_cuenta_corriente
            WHERE id = (v_pago->>'id_cliente_cuenta')::UUID 
              AND id_tenant = p_id_tenant
            FOR UPDATE;

            IF NOT FOUND THEN
                RAISE EXCEPTION 'Cliente de cuenta corriente no encontrado.';
            END IF;
        END IF;
    END LOOP;

    -- 4. Procesar ítems, descontar inventario con bloqueo de fila (Supermercado / ABC)
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        -- Bloquear stock del producto para este tenant
        SELECT stock_actual INTO v_stock_actual
        FROM inventario_sucursal
        WHERE id_producto = (v_item->>'id_producto')::UUID 
          AND id_tenant = p_id_tenant
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Producto % no encontrado en inventario.', (v_item->>'id_producto');
        END IF;

        IF v_stock_actual < (v_item->>'cantidad')::NUMERIC THEN
            RAISE EXCEPTION 'Stock insuficiente para el producto %. Stock actual: %, Solicitado: %', 
                (v_item->>'id_producto'), v_stock_actual, (v_item->>'cantidad');
        END IF;

        -- Descontar inventario
        UPDATE inventario_sucursal
        SET stock_actual = stock_actual - (v_item->>'cantidad')::NUMERIC,
            updated_at = NOW()
        WHERE id_producto = (v_item->>'id_producto')::UUID 
          AND id_tenant = p_id_tenant;

        v_monto_total := v_monto_total + ((v_item->>'cantidad')::NUMERIC * (v_item->>'precio_unitario')::NUMERIC);
    END LOOP;

    -- 5. Validar cuadre financiero (Tolerancia estricta)
    IF ABS(v_suma_pagos - v_monto_total) > 0.01 THEN
        RAISE EXCEPTION 'Descuadre financiero: La suma de pagos (%) no coincide con el total de la comanda (%).', 
            v_suma_pagos, v_monto_total;
    END IF;

    -- 6. Generar Cabecera de Factura / Ticket
    INSERT INTO facturas (id_tenant, id_caja, id_comanda, monto_total, estado, created_at)
    VALUES (p_id_tenant, p_id_caja, p_id_comanda, v_monto_total, 'PAGADA', NOW())
    RETURNING id INTO v_id_factura;

    -- 7. Registrar los pagos divididos y afectar cuentas corrientes si aplica
    FOR v_pago IN SELECT * FROM jsonb_array_elements(p_pagos)
    LOOP
        INSERT INTO pagos_factura (id_tenant, id_factura, metodo, monto, referencia_externa, banco_emisor)
        VALUES (
            p_id_tenant, 
            v_id_factura, 
            v_pago->>'metodo', 
            (v_pago->>'monto')::NUMERIC, 
            v_pago->>'referencia_externa', 
            v_pago->>'banco_emisor'
        );

        IF v_pago->>'metodo' = 'CUENTA_CORRIENTE' THEN
            UPDATE clientes_cuenta_corriente
            SET saldo_actual = saldo_actual + (v_pago->>'monto')::NUMERIC,
                updated_at = NOW()
            WHERE id = (v_pago->>'id_cliente_cuenta')::UUID 
              AND id_tenant = p_id_tenant;

            INSERT INTO movimientos_cuenta_corriente (id_tenant, id_cliente, id_factura, tipo, monto, created_at)
            VALUES (
                p_id_tenant, 
                (v_pago->>'id_cliente_cuenta')::UUID, 
                v_id_factura, 
                'CARGO', 
                (v_pago->>'monto')::NUMERIC, 
                NOW()
            );
        END IF;
    END LOOP;

    -- 8. Actualizar estado de la comanda a COMPLETADA
    UPDATE comandas
    SET estado = 'COMPLETADA',
        updated_at = NOW()
    WHERE id = p_id_comanda 
      AND id_tenant = p_id_tenant;

    -- 9. Retornar respuesta exitosa estructurada
    RETURN jsonb_build_object(
        'status', 'success',
        'id_factura', v_id_factura,
        'monto_procesado', v_monto_total
    );

EXCEPTION WHEN OTHERS THEN
    -- Rollback automático garantizado por PostgreSQL en bloques PL/pgSQL
    RAISE;
END;
$$;
```

